roads = {"B-A": 10, "A-C": 12, "C-B": 20, "E-A": 7, "A-D": 60, "C-D": 32}   # Figure 4.11
path = ["E", "A", "C", "D"]

cost, possible = 0, True
for i in range(len(path) - 1):
    road = path[i] + "-" + path[i + 1]
    if road in roads:
        cost = cost + roads[road]
        print(road, "costs", roads[road])
    else:
        print("No one-way road", road)
        possible = False
if possible:
    print("Total cost of", "-".join(path), "=", cost)
